export async function callDownstreamService(url: string, payload: any, timeoutMs = 2000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify(payload),
      signal: controller.signal,
      headers: { 'Content-Type': 'application/json' },
    });
    return await response.json();
  } catch (err: any) {
    if (err.name === 'AbortError') {
      throw new Error(`Downstream call to ${url} timed out after ${timeoutMs}ms`);
    }
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

export async function executeWithRetry<T>(
  operation: () => Promise<T>,
  maxAttempts = 3,
  baseMs = 100,
  maxMs = 2000
): Promise<T> {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await operation();
    } catch (err: any) {
      if (attempt === maxAttempts || !isTransientError(err)) {
        throw err;
      }
      const backoff = Math.min(maxMs, baseMs * Math.pow(2, attempt - 1));
      await new Promise(r => setTimeout(r, backoff));
    }
  }
  throw new Error('Retries exhausted');
}

export class JitterBackoff {
  // Full Jitter: Uniformly random between 0 and exponential ceiling
  static fullJitter(attempt: number, baseMs = 100, capMs = 5000): number {
    const exponentialCeiling = Math.min(capMs, baseMs * Math.pow(2, attempt));
    return Math.floor(Math.random() * exponentialCeiling);
  }

  // Equal Jitter: Half deterministic backoff, half randomized jitter
  static equalJitter(attempt: number, baseMs = 100, capMs = 5000): number {
    const ceiling = Math.min(capMs, baseMs * Math.pow(2, attempt));
    const half = Math.floor(ceiling / 2);
    return half + Math.floor(Math.random() * half);
  }
}

type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export class CircuitBreaker {
  private state: CircuitState = 'CLOSED';
  private failureCount = 0;
  private nextAttempt = Date.now();

  constructor(private threshold = 5, private resetTimeoutMs = 30000) {}

  async execute<T>(action: () => Promise<T>, fallback: () => T): Promise<T> {
    if (this.state === 'OPEN') {
      if (Date.now() > this.nextAttempt) {
        this.state = 'HALF_OPEN'; // Attempt canary probe
      } else {
        return fallback(); // Fail fast without making network call!
      }
    }

    try {
      const result = await action();
      if (this.state === 'HALF_OPEN') {
        this.state = 'CLOSED';
        this.failureCount = 0;
      }
      return result;
    } catch (err) {
      this.failureCount++;
      if (this.failureCount >= this.threshold || this.state === 'HALF_OPEN') {
        this.state = 'OPEN';
        this.nextAttempt = Date.now() + this.resetTimeoutMs;
      }
      return fallback();
    }
  }
}

export class BulkheadSemaphore {
  private inFlight = 0;

  constructor(private maxConcurrent: number, private maxQueue: number) {}

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this.inFlight >= this.maxConcurrent + this.maxQueue) {
      // Bulkhead capacity saturated! Reject immediately to preserve other services
      throw new Error('Bulkhead capacity exceeded (Shedding load)');
    }

    this.inFlight++;
    try {
      return await action();
    } finally {
      this.inFlight--;
    }
  }
}

export async function executeAutomatedFailover(primaryNode: Node, standbyNode: Node) {
  console.warn(`Primary ${primaryNode.id} failed 3 consecutive heartbeats!`);

  // Step 1: FENCE old primary to prevent split-brain writes (STONITH)
  const fenced = await fenceNode(primaryNode.id);
  if (!fenced) {
    throw new Error('Fencing failed! Aborting failover to avoid split-brain data corruption.');
  }

  // Step 2: Promote standby only AFTER confirming old primary is dead
  await standbyNode.promoteToPrimary();
  console.log(`Standby ${standbyNode.id} successfully promoted to primary.`);
}

export async function getProductDetails(productId: string) {
  // Hard dependency: Must succeed or entire page fails
  const product = await catalogService.fetchById(productId);

  // Soft dependencies: Wrapped in safe error boundaries with fallbacks
  const [reviews, recommendations] = await Promise.all([
    reviewService.fetchReviews(productId).catch(() => {
      console.warn(`Review service unavailable for ${productId}; returning empty list`);
      return []; // Return empty review list
    }),
    recommendationService.fetchPersonalized(productId).catch(() => {
      // Fall back to pre-rendered static top-sellers
      return staticCatalog.getTopSellers();
    }),
  ]);

  return { ...product, reviews, recommendations };
}

enum PriorityTier {
  P0_CHECKOUT = 0,     // Never drop
  P1_INTERACTIVE = 1,  // Drop under extreme load
  P2_BACKGROUND = 2,   // Drop when queue depth > 50
  P3_SCRAPERS = 3,     // Drop first when CPU > 75%
}

export function loadSheddingMiddleware(req: Request, res: Response, next: NextFunction) {
  const tier = extractPriorityTier(req);
  const currentCpuUsage = getProcessCpuPercentage();
  const queueDepth = getActiveQueueDepth();

  // Progressively shed lower priority cohorts
  if (currentCpuUsage > 80 && tier >= PriorityTier.P3_SCRAPERS) {
    return res.status(429).setHeader('Retry-After', '30').send('Rate limit exceeded');
  }
  if (queueDepth > 100 && tier >= PriorityTier.P2_BACKGROUND) {
    return res.status(503).setHeader('Retry-After', '10').send('Service temporarily congested');
  }

  next(); // Admit high-priority traffic
}
